values = [7, 2, 5, 1]
a = values[:]
for i in range(len(a)):
    smallest = i
    for j in range(i + 1, len(a)):
        if a[j] < a[smallest]:
            smallest = j
    a[i], a[smallest] = a[smallest], a[i]
print('Selection:', a)

b = values[:]
for stop in range(len(b) - 1, 0, -1):
    for j in range(stop):
        if b[j] > b[j + 1]:
            b[j], b[j + 1] = b[j + 1], b[j]
print('Bubble:', b)
